-- 把同一訂單內，所有餐點都是取消(2)的 PreOrder，狀態改成 2
UPDATE PreOrders
SET DoneOrCancel = 2
WHERE DoneOrCancel = 0
  AND Id IN (
      SELECT PreOrderId
      FROM PreOrderDetails
      GROUP BY PreOrderId
      HAVING COUNT(*) = SUM(CASE WHEN DoneOrCancel = 2 THEN 1 ELSE 0 END)
  );

-- 1. 有已完成餐點 → 改成 1
UPDATE PreOrders
SET DoneOrCancel = 1
WHERE DoneOrCancel = 0
  AND Id IN (
      SELECT PreOrderId
      FROM PreOrderDetails
      WHERE DoneOrCancel = 1
  );

-- 2. 所有餐點都取消 → 改成 2
UPDATE PreOrders
SET DoneOrCancel = 2
WHERE DoneOrCancel = 0
  AND Id IN (
      SELECT PreOrderId
      FROM PreOrderDetails
      GROUP BY PreOrderId
      HAVING COUNT(*) = SUM(CASE WHEN DoneOrCancel = 2 THEN 1 ELSE 0 END)
  );

-- 3. 已取消的訂單補上 CancelledAt（用 OrderAt 加 30 分鐘模擬取消時間）
UPDATE PreOrders
SET CancelledAt = DATEADD(MINUTE, 30, OrderAt)
WHERE DoneOrCancel = 2
  AND CancelledAt IS NULL;

--------------------------------------------------------------------------
  -- 先全部歸零
UPDATE [dbo].[PreOrderDetails]
SET [IsBilled] = 0;
GO

-- 餐點 DoneOrCancel=1 且主單 DoneOrCancel=1 → 已結帳
UPDATE pd
SET pd.[IsBilled] = 1
FROM [dbo].[PreOrderDetails] pd
INNER JOIN [dbo].[PreOrders] po ON pd.[PreOrderId] = po.[Id]
WHERE pd.[DoneOrCancel] = 1
  AND po.[DoneOrCancel] = 1;
GO

-- 標記套餐標題
UPDATE pd
SET pd.[IsSetMeal] = 1
FROM [dbo].[PreOrderDetails] pd
JOIN [dbo].[Products] p ON pd.[ProductId] = p.[Id]
WHERE p.[ProductType] = 'SetMeal';
GO